# Заменитель компилятора: падает, если файл с классом, на который ссылается
# любой файл дерева, отсутствует. Тесты здесь такие же ссылающиеся файлы, как и
# остальной код, — в этом смысл случая про пару.
#
# Граница слова обязательна: без неё `orphanTest()` давало ссылку на `Test`,
# и заменитель требовал Test.kt. Ровно та же ошибка подстроки, из-за которой в
# самом инструменте `bound()` написан руками, а не через grep -w.
for c in $(cat *.kt 2>/dev/null | grep -oE '(^|[^A-Za-z0-9_])[A-Z][A-Za-z0-9_]*\(\)' \
           | sed 's/^[^A-Za-z0-9_]*//' | tr -d '()' | sort -u); do
    if [ ! -f "$c.kt" ]; then
        echo "error: unresolved reference: $c"
        exit 1
    fi
done
echo "BUILD OK"
